<?php require_once 'layout.php'; header_admin('Imágenes');
$sql='SELECT im.id, im.programa_id AS program_id, im.pagina_id AS page_id, im.etiqueta AS label, im.ruta_imagen AS image_path, im.nombre_original AS original_name, im.seccion_referencia AS section_hint, im.creado_en AS created_at, pr.codigo AS code, p.titulo AS page_title FROM imagenes_pagina im JOIN programas pr ON im.programa_id=pr.id LEFT JOIN paginas p ON im.pagina_id=p.id'; $params=[]; if(!is_admin()){ $sql.=' WHERE pr.codigo=?'; $params[]=user()['program_code']; } $sql.=' ORDER BY im.id DESC LIMIT 300'; $st=$pdo->prepare($sql); $st->execute($params); $imgs=$st->fetchAll(PDO::FETCH_ASSOC); ?>
<div class="row g-3"><?php foreach($imgs as $im): ?><div class="col-md-3"><div class="card main-card h-100"><img src="../../<?=e($im['image_path'])?>" class="card-img-top" style="height:150px;object-fit:cover;border-radius:24px 24px 0 0"><div class="card-body"><span class="program-pill"><?=e($im['code'])?></span><h6 class="fw-bold mt-2"><?=e($im['label'])?></h6><small class="text-muted"><?=e($im['page_title']??'General')?></small><input class="form-control form-control-sm mt-2" value="<?=e($im['image_path'])?>" readonly></div></div></div><?php endforeach; ?></div><?php footer_admin(); ?>